#!/usr/bin/env python3
"""Build a dependency-free GitHub Pages site from shared templates."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[1]
DOMAIN='https://openroadmovingandstorage.com'
CONFIG=json.loads((ROOT/'site-config.json').read_text())
PHONE=CONFIG['phone']
EMAIL=CONFIG['quote_email']
ACCESS_KEY=CONFIG['web3forms_access_key']

def icon(kind):
 paths={'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>','phone':'<path d="M7 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a14 14 0 0 1-7-7l2-2-2-5Z"/>','truck':'<path d="M3 5h11v12H3zM14 9h4l3 4v4h-7M3 17h2m5 0h6m4 0h1"/><circle cx="7.5" cy="18" r="2.5"/><circle cx="18" cy="18" r="2.5"/>','box':'<path d="m12 3 9 5v10l-9 5-9-5V8l9-5Zm-9 5 9 5 9-5M12 13v10M7.5 5.5l9 5"/>','storage':'<path d="m3 8 9-5 9 5v13H3V8Zm3 13V11h12v10M6 14h12M6 17h12"/>'}
 return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+paths.get(kind,paths['arrow'])+'</svg>'

def call(cls='button outline',label='Call for a quote'):
 return f'<a class="{cls}" href="tel:{PHONE}">{icon("phone")}{label}</a>'

def quote(cls='button',label='Get my moving quote'):
 return f'<a class="{cls}" href="/get-a-quote/">{label}{icon("arrow")}</a>'

def header(active=''):
 links=[('/long-distance-moving/','Services'),('/how-it-works/','How It Works'),('/service-areas/','Service Areas'),('/about/','About')]
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+f'>{name}</a>' for url,name in links)
 return f'''<a class="skip" href="#main">Skip to content</a><div class="topline">A new address. An open road.</div><header class="header"><div class="container header-inner"><a class="brand" href="/" aria-label="Open Road Moving and Storage home"><img src="/assets/logo.webp" width="1000" height="170" alt="Open Road Moving &amp; Storage"></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-nav" aria-label="Open navigation">☰ <span>Menu</span></button><nav class="nav" id="primary-nav" aria-label="Main navigation">{nav}{call('button')}</nav></div></header>'''

def footer():
 return f'''<section class="cta-band"><div class="container cta-inner"><div><h2>Your next chapter starts here.</h2><p>Share your route and dates. Let’s talk through the move.</p></div><div class="cta-actions">{quote()}{call()}</div></div></section><footer class="footer"><div class="container"><div class="footer-grid"><div><a class="footer-brand" href="/"><img src="/assets/icon.webp" width="64" height="40" alt=""><span>OPEN ROAD<small>MOVING &amp; STORAGE</small></span></a><p>Long-distance moving starts with a clear plan.<br>Pickup coverage across Texas, the Midwest and Northeast. Ask about your route.</p>{call('text-link')}</div><div><h3>Plan your move</h3><div class="footer-links"><a href="/long-distance-moving/">Long-distance moving</a><a href="/packing-and-storage/">Packing &amp; storage options</a><a href="/service-areas/">Service areas</a><a href="/moving-estimates/">Understanding your estimate</a></div></div><div><h3>Get to know Open Road</h3><div class="footer-links"><a href="/how-it-works/">How it works</a><a href="/about/">About Open Road</a><a href="/faqs/">Moving FAQs</a><a href="/get-a-quote/">Contact &amp; quote request</a></div></div></div><div class="footer-bottom"><div>© 2026 Open Road Moving &amp; Storage.<br>USDOT 3266915 · MC 1030727</div><div><a href="/privacy/">Privacy</a> &nbsp;·&nbsp; <a href="/terms/">Website terms</a><br>Service availability and scheduling are confirmed for each move.</div></div></div></footer><div class="mobile-bar" aria-label="Quick contact">{call()}{quote(label='Get a quote')}</div>'''

def form(prefix='quote'):
 def field(name,label,typ='text',placeholder='',extra='',full=False):
  return f'<label class="{"full" if full else ""}" for="{prefix}-{name}">{label}<input id="{prefix}-{name}" name="{name}" type="{typ}" placeholder="{placeholder}" {extra}></label>'
 return f'''<form class="quote-form" action="https://api.web3forms.com/submit" method="POST" enctype="multipart/form-data"><input type="hidden" name="access_key" value="{ACCESS_KEY}"><input type="hidden" name="subject" value="Open Road — New moving quote request"><input type="hidden" name="from_name" value="Open Road Moving &amp; Storage"><input type="hidden" name="redirect" value="{DOMAIN}/thank-you/"><input type="hidden" name="source" value="Open Road website"><div class="honey" aria-hidden="true"><label>Leave this field empty<input type="checkbox" name="botcheck" tabindex="-1" autocomplete="off"></label></div><p class="form-progress" aria-live="polite">Step 1 of 3 · Your move</p><fieldset data-step><legend>Your move</legend><div class="field-grid">{field('pickup_zip','Moving from ZIP',placeholder='e.g. 75201',extra='required inputmode="numeric" pattern="[0-9]{5}" maxlength="5" autocomplete="off" title="Enter a 5-digit U.S. ZIP code"')}{field('delivery_zip','Moving to ZIP',placeholder='e.g. 60601',extra='required inputmode="numeric" pattern="[0-9]{5}" maxlength="5" autocomplete="off" title="Enter a 5-digit U.S. ZIP code"')}{field('move_date','Move date','date',extra='required')}<label for="{prefix}-home_size">Home size<select id="{prefix}-home_size" name="home_size" required><option value="">Select size</option><option>Studio</option><option>1 bedroom</option><option>2 bedrooms</option><option>3 bedrooms</option><option>4+ bedrooms</option><option>Partial move / other</option></select></label></div></fieldset><fieldset data-step><legend>A little about your move</legend><div class="field-grid"><label class="full" for="{prefix}-services">What would help?<select id="{prefix}-services" name="services" required><option value="">Select an option</option><option>Moving only</option><option>Moving + packing</option><option>Moving + storage</option><option>Moving + packing + storage</option><option>Help me decide</option></select></label><label class="full" for="{prefix}-notes">Move notes <span>(optional)</span><textarea id="{prefix}-notes" name="move_notes" rows="3" maxlength="3000" placeholder="Large items, stairs, elevators, flexible dates…"></textarea></label></div></fieldset><fieldset data-step><legend>Where can we reach you?</legend><div class="field-grid">{field('name','Full name',placeholder='Your name',extra='required autocomplete="name" maxlength="150"',full=True)}{field('phone','Phone number','tel',placeholder='Best callback number',extra='required autocomplete="tel" minlength="10" maxlength="30" pattern="[+0-9&#92;(&#92;) .&#92;-]{10,30}"',full=True)}{field('email','Email address','email',placeholder='you@example.com',extra='required autocomplete="email" maxlength="254"',full=True)}<label class="consent full" for="{prefix}-consent"><input id="{prefix}-consent" type="checkbox" name="contact_permission" value="Requested phone/email follow-up about this move" required><span>By submitting, you ask Open Road Moving &amp; Storage to contact you by phone or email about this move. No purchase required. <a href="/privacy/">Privacy policy</a>.</span></label></div></fieldset><div class="form-actions"><button type="button" class="button outline form-back" data-back hidden>Back</button><button type="button" class="button form-next" data-next>Start my quote {icon('arrow')}</button><button type="submit" class="button" data-submit>Request my quote {icon('arrow')}</button></div><p class="form-small">Tell us your route. We’ll confirm availability.<br>A request doesn’t reserve a move or set a price.</p><p class="form-status" role="status" hidden></p></form>'''

FAQ=[('Where can you pick up my move?','Pickup coverage is concentrated in Texas, the Midwest—including Illinois and Wisconsin—and the Northeast. Share both ZIP codes and your preferred date so we can confirm your specific route before you make plans.'),('How is my moving estimate calculated?','Your inventory, route, dates, packing needs, storage and access conditions all affect the estimate. Stairs, elevators and a long distance between the truck and your door can affect the work involved. Ask for the included services and any possible additional charges in writing.'),('Is my delivery date guaranteed?','Do not assume a requested date is a guaranteed date. Pickup and delivery arrangements, including any delivery window, must be confirmed in your written moving agreement. Ask about timing before booking.'),('Can I request packing or storage?','Yes—include packing or storage needs in your request. Availability, storage location, duration, handling and charges must be confirmed for your move before booking.'),('What happens after I request a quote?','You’ll be contacted to review the route, dates, inventory and access details. Your written estimate and agreement identify the company handling your move and the services and terms that apply.'),('What if my inventory or dates change?','Contact the team before pickup. Changes to your inventory, requested services or schedule may require a revised estimate or different availability. Review any revised terms before agreeing.')]
def faqs(items=FAQ):
 return '<div class="faq-list">'+''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in items)+'</div>'

PAGES={}
def page(path,title,description,body,hero=None,aside=True,noindex=False):
 url=DOMAIN+path
 schema={'@context':'https://schema.org','@type':'Organization','name':'Open Road Moving & Storage','url':DOMAIN,'logo':DOMAIN+'/assets/logo.webp','legalName':'TX Moving and Storage LLC','telephone':PHONE,'identifier':['USDOT 3266915','MC 1030727']}
 meta=f'<title>{escape(title)} | Open Road Moving &amp; Storage</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Open Road"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{DOMAIN}/assets/open-road-hero.webp"><meta name="twitter:card" content="summary_large_image">'
 if noindex: meta+='<meta name="robots" content="noindex,follow">'
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">{meta}<meta name="theme-color" content="#103e31"><link rel="icon" href="/assets/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="512x512" href="/assets/icon-512.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{header(path)}<main id="main">'''
 if hero:
  h,lead=hero
  doc+=f'<section class="page-hero"><div class="container"><div class="breadcrumb"><a href="/">Home</a> / {escape(title)}</div><span class="eyebrow">OPEN ROAD MOVING &amp; STORAGE</span><h1>{h}</h1><p class="lead">{lead}</p></div></section>'
 doc+=body+'</main>'+footer()+'</body></html>'
 target=ROOT/('index.html' if path=='/' else path.strip('/')+'/index.html'); target.parent.mkdir(parents=True,exist_ok=True); target.write_text(doc)
 PAGES[path]={'title':title,'description':description,'noindex':noindex}

def article(content):
 return f'<section class="page-body"><div class="container article-layout"><article class="prose">{content}</article><aside class="aside-card"><span class="eyebrow">LET’S TALK IT THROUGH</span><h2>A clear plan starts with your details.</h2><p>Have your pickup and delivery ZIP codes, preferred date and a quick inventory ready.</p>{quote(label="Request a quote")}{call()}</aside></div></section>'

home=f'''<section class="hero"><img class="hero-photo" src="/assets/open-road-hero.webp" srcset="/assets/open-road-hero-small.webp 960w, /assets/open-road-hero.webp 1672w" sizes="100vw" width="1672" height="941" fetchpriority="high" alt="An open road winding through green hills toward the horizon"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">LONG-DISTANCE MOVING</span><h1>A new address.<br>An open road.</h1><p>Moving across state lines?<br>Let’s plan your next chapter.</p><div class="hero-actions">{quote()}{call()}</div><p class="hero-foot">Your route. Your dates. A conversation first.</p></div><div class="quote-card" id="quick-quote"><h2>Where are you headed?</h2><p class="card-intro">A few details. A clearer next step.</p>{form('home')}<a class="card-call" href="tel:{PHONE}">Prefer to talk? Call for a quote ↗</a></div></div></section><section class="step-strip" aria-label="How your move starts"><div class="container steps"><div class="step"><span class="step-num">1</span><div><h3>Share your move</h3><p>Your route, your dates and what’s coming.</p></div></div><div class="step"><span class="step-num">2</span><div><h3>Review your estimate</h3><p>Understand the services and charges.</p></div></div><div class="step"><span class="step-num">3</span><div><h3>Confirm your plan</h3><p>Review the details before you book.</p></div></div></div></section><section class="section"><div class="container services-grid"><div><span class="eyebrow">ROOM FOR WHAT’S NEXT</span><h2>Big moves.<br>Clear next steps.</h2><p class="intro-copy">A long-distance move has a lot of moving parts. Start with the right questions, a thoughtful inventory and a written plan for your next address.</p><div class="service-list"><div class="service-item">{icon('truck')}<h3>Interstate moves</h3><p>Plan the route, dates and details of your state-to-state move.</p><a class="text-link" href="/long-distance-moving/">Explore moving →</a></div><div class="service-item">{icon('box')}<h3>Packing options</h3><p>Discuss help with fragile pieces, furniture and the everyday essentials.</p><a class="text-link" href="/packing-and-storage/">Plan your packing →</a></div><div class="service-item">{icon('storage')}<h3>Storage options</h3><p>Ask about options when your move-out and move-in dates don’t line up.</p><a class="text-link" href="/packing-and-storage/#storage">Explore storage →</a></div></div></div><div><img class="home-photo" src="/assets/a-new-chapter.webp" width="1200" height="900" loading="lazy" alt="Carefully packed moving boxes in a sunlit living room"><p class="photo-caption">Make room for your next chapter.</p></div></div></section><section class="section coverage"><div class="container"><div class="section-heading"><div><span class="eyebrow">LET’S FIND YOUR WAY FORWARD</span><h2>A national outlook.<br>A plan for your route.</h2></div><p>Our pickup coverage is centered on Texas, the Midwest and Northeast. Tell us where you’re starting and where life is taking you.</p></div><div class="region-list"><div class="region"><span class="region-number">01 / TEXAS</span><h3>Big plans start here.</h3><p>Moving out of Texas? Share your origin city and destination to discuss the next steps.</p><a class="text-link" href="/service-areas/texas/">Texas pickups →</a></div><div class="region"><span class="region-number">02 / MIDWEST</span><h3>Your next direction.</h3><p>Pickup coverage includes Illinois and Wisconsin. Ask about your city, dates and destination.</p><a class="text-link" href="/service-areas/midwest/">Midwest pickups →</a></div><div class="region"><span class="region-number">03 / NORTHEAST</span><h3>A fresh beginning.</h3><p>Planning a move from the Northeast? We’ll review your route and building access before booking.</p><a class="text-link" href="/service-areas/northeast/">Northeast pickups →</a></div></div><div class="coverage-bottom"><p>Coverage is confirmed for each move. Pickup availability, destination, inventory and dates all matter. Have another origin in mind? Ask us.</p>{quote('button light','Check my route')}</div></div></section><section class="section"><div class="container split"><div><span class="eyebrow">KNOW WHAT COMES NEXT</span><h2>Confidence starts<br>with clarity.</h2><p class="intro-copy">Before you book, know what’s included, how timing works and who to contact. Your written documents should make those details clear.</p><ul class="checklist"><li>An inventory that reflects what you’re actually moving.</li><li>Packing, storage and access needs discussed up front.</li><li>Your moving company and booking terms identified in writing.</li></ul><a class="text-link" href="/moving-estimates/">Understand your moving estimate →</a></div><div><span class="eyebrow">A FEW GOOD QUESTIONS</span>{faqs(FAQ[:4])}<a class="text-link" href="/faqs/" style="margin-top:22px">More moving questions →</a></div></div></section>'''
page('/','Long-Distance Moving for Your Next Chapter','Plan your interstate move with Open Road Moving & Storage. Texas, Midwest and Northeast pickup coverage. Request a quote or call about your route.',home)

page('/long-distance-moving/','Long-Distance & Interstate Moving','Discuss your interstate move, inventory, dates and access needs. Open Road pickup coverage is centered on Texas, the Midwest and Northeast.',article('''<h2>A thoughtful start to a bigger move.</h2><p>Crossing state lines takes more than a destination ZIP code. Your inventory, building access, packing needs and timing shape the plan. Start by sharing the move you actually need, so those details can be reviewed before you book.</p><h2>What to have ready</h2><ul><li>Pickup and delivery addresses or ZIP codes, plus any flexibility in dates.</li><li>A room-by-room inventory, including large or unusually fragile items.</li><li>Stairs, elevators, parking restrictions and the distance from the truck to your door.</li><li>Any packing, unpacking or storage help you want included.</li></ul><h2>Timing deserves its own conversation.</h2><p>Ask whether pickup and delivery are scheduled for specific dates or a delivery window. Discuss access hours, travel plans and what happens if your destination is not ready. A requested date is not a guarantee unless your written agreement says so.</p><h2>Know the company and the terms.</h2><p>Your written moving estimate and agreement should identify the company handling your move, the services included, the applicable charges and the contact for shipment updates. Review these before paying or signing.</p><p>Open Road Moving &amp; Storage is operated by TX Moving and Storage LLC. Company identifiers: USDOT 3266915 and MC 1030727.</p><h2>Start with your route.</h2><p>Pickup coverage is centered on Texas, the Midwest and Northeast. Availability is reviewed for your origin, destination, inventory and dates.</p><p><a href="/service-areas/">Explore pickup coverage</a> or <a href="/get-a-quote/">request your moving quote</a>.</p>'''),hero=('A bigger move.<br>A clearer plan.','Long-distance moving begins with your route, your inventory and a conversation about the details.'))

page('/packing-and-storage/','Packing & Storage Options','Discuss packing, furniture preparation and storage requirements for your long-distance move. Confirm available services and charges before booking.',article('''<h2>The details matter before the first box.</h2><p>Tell us what you want to pack yourself and what you would like help with. Packing supplies, labor, furniture preparation and specialty-item handling should be itemized in your estimate when included.</p><h2>Packing options to discuss</h2><ul><li>Full-home packing or help with selected rooms and fragile items.</li><li>Furniture preparation, disassembly and reassembly requirements.</li><li>Materials needed for mirrors, artwork, electronics or unusually shaped items.</li><li>What unpacking and removal of packing materials include, if requested.</li></ul><p>Availability depends on your move. Do not assume boxes, packing labor or special handling are included unless your written estimate lists them.</p><h2 id="storage">When your dates don’t line up.</h2><p>If you need time between pickup and delivery, ask about available storage options before booking. Confirm the facility, access arrangements, handling charges, billing period and the process for scheduling delivery out of storage.</p><h2>Keep the essentials with you.</h2><p>Plan to keep medications, identification, important paperwork, keys and daily essentials out of the shipment. Ask for the applicable list of prohibited items before packing. Do not pack hazardous materials without checking the moving company’s requirements.</p><h2>Put your requests in writing.</h2><p>Include packing or storage needs in your quote request so they can be reviewed with your inventory and schedule. Your final service agreement controls what is included.</p>'''),hero=('A little more help.<br>A lot more clarity.','Discuss packing and storage options that fit your move—and confirm the details before moving day.'))

page('/service-areas/','Moving Pickup & Service Areas','Explore Open Road pickup coverage in Texas, the Midwest including Illinois and Wisconsin, and the Northeast. Confirm availability for your route.',article('''<h2>Tell us your starting point.</h2><p>Open Road has a national long-distance focus, with pickup coverage centered on Texas, the Midwest and Northeast. Availability is confirmed for each route and date, rather than assumed from a broad service-area label.</p><div class="coverage-links"><div class="coverage-tile"><h2>Texas</h2><p>Planning an out-of-state move from Texas?</p><a href="/service-areas/texas/">Explore Texas pickups →</a></div><div class="coverage-tile"><h2>Midwest</h2><p>Including Illinois and Wisconsin origins.</p><a href="/service-areas/midwest/">Explore Midwest pickups →</a></div><div class="coverage-tile"><h2>Northeast</h2><p>Review your origin, access and timing.</p><a href="/service-areas/northeast/">Explore Northeast pickups →</a></div></div><h2>Origins and destinations are different.</h2><p>A destination we can discuss for a Texas departure does not automatically mean pickup is available from every city in that destination state. Share both ZIP codes and the preferred date so the team can confirm the full route.</p><h2>Have another origin in mind?</h2><p>Ask about it. We will review your request and tell you whether that pickup can be accommodated. A quote request does not reserve a truck, crew or date.</p>'''),hero=('Where you are.<br>Where you’re headed.','Texas, Midwest and Northeast pickups. A long-distance plan built around your actual route.'))

regions={
 'texas':('Texas','Plan your next chapter beyond Texas.','Texas is a core pickup region. Share your origin city, destination ZIP code and preferred move date to discuss an interstate move.','For a Texas pickup, include neighborhood parking restrictions, gates, apartment access and any long walk from the truck to your door. If you have a storage unit as well as a home pickup, include both stops in your request.','Discuss travel plans around the written pickup and delivery arrangements. Summer heat, community access rules and building reservations are useful details to raise during planning.'),
 'midwest':('Midwest','A fresh start from the Midwest.','Midwest pickup coverage includes Illinois and Wisconsin. Other origins can be reviewed on request; share the city and ZIP code rather than assuming coverage from the regional label.','For city apartments, explain elevator reservations, loading zones, parking permits and stairs. For suburban or rural homes, include driveway clearance and the distance to the entrance.','Cold-weather moves need a practical access plan. Discuss snow-cleared entrances, building hours and weather-related scheduling questions before pickup.'),
 'northeast':('Northeast','Your next chapter, beyond the Northeast.','Planning an interstate move from the Northeast? Share your exact origin and destination ZIP codes so pickup coverage and route availability can be confirmed.','Narrow streets, walk-ups, elevator booking windows and loading restrictions can change the work involved. Include these details, plus any building-requested insurance documentation, during the estimate process.','If your building limits move-in or move-out hours, tell the team before scheduling. Ask how those restrictions fit with the proposed pickup and delivery arrangements.')}
for slug,(region,headline,intro,access,timing) in regions.items():
 page('/service-areas/'+slug+'/',region+' Long-Distance Moving Pickups',f'Plan a long-distance move from the {region} region. Discuss pickup availability, inventory, building access and your written moving estimate.',article(f'''<h2>{headline}</h2><p>{intro}</p><h2>Access details worth sharing.</h2><p>{access}</p><h2>Make room for timing.</h2><p>{timing}</p><h2>A useful quote starts with a useful inventory.</h2><p>List the furniture, boxes and specialty items you want to move. Identify what you will pack yourself and whether you need storage between homes. Ask how changes to those details would affect your estimate.</p><h2>Confirm before committing.</h2><p>Pickup availability depends on your origin, destination, dates and shipment. Review the written estimate, company identity, payment schedule, cancellation terms and delivery arrangements before booking.</p><p><a href="/service-areas/">See all pickup regions</a> or <a href="/get-a-quote/">share your route</a>.</p>'''),hero=(region+' departures.<br>New possibilities.','Tell us where you’re starting, where you’re going and the date you have in mind.'))

page('/how-it-works/','How Your Moving Quote Works','From first inquiry to a written moving plan: learn what to expect when requesting a long-distance quote from Open Road Moving & Storage.',article('''<h2>1. Share your move.</h2><p>Start with your pickup ZIP, destination ZIP, preferred date and home size. Add packing or storage needs and a way to reach you. Your request is an inquiry, not a reservation or a binding estimate.</p><h2>2. Review the details.</h2><p>Discuss a room-by-room inventory, access at both ends and the timing you need. Share photos or arrange a more detailed inventory review if requested. Confirm that the estimate reflects the services you want.</p><h2>3. Read your written estimate.</h2><p>Review the moving company’s identity, estimate type, included services, potential additional charges, payment schedule and cancellation terms. Ask about any item you do not understand before agreeing.</p><h2>4. Confirm the moving plan.</h2><p>Once you decide to book, confirm pickup arrangements, delivery timing or window, and the contact for updates. Keep copies of your estimate and agreement. If your inventory or schedule changes, request an updated written plan.</p><h2>5. Prepare for pickup and delivery.</h2><p>Keep essentials with you, make the agreed access arrangements and review the shipment inventory and condition records. At delivery, note any concerns on the appropriate paperwork and ask for the written claims procedure if needed.</p>'''),hero=('From first question<br>to moving-day plan.','Five practical steps to help you understand what happens next.'))

page('/moving-estimates/','Understanding Your Moving Estimate','Learn which details affect a long-distance moving estimate: inventory, route, packing, storage, access, payment terms and delivery arrangements.',article('''<h2>Your move is more than a bedroom count.</h2><p>Home size is a starting point. A useful estimate also considers what you are moving, the route, service requirements and access at each stop. Give a complete inventory and ask how the charges are calculated.</p><h2>Details that may affect the price</h2><ul><li>Shipment size and the items included in the inventory.</li><li>Pickup and delivery locations, extra stops and requested dates.</li><li>Packing materials, packing labor and specialty-item handling.</li><li>Stairs, elevators, long carries and access limitations.</li><li>Storage, additional handling and requested extra services.</li></ul><h2>Understand the estimate type.</h2><p>Ask whether the written estimate is binding or nonbinding, what that means for your move and which services it covers. Do not treat a phone conversation or a website request as the final written price.</p><h2>Ask these questions before booking.</h2><ol><li>Which legal company is responsible for my move?</li><li>What inventory and services does this estimate include?</li><li>Which circumstances could create additional charges?</li><li>What are the payment, deposit and cancellation terms?</li><li>What pickup and delivery arrangements are actually confirmed?</li><li>What valuation options and claims procedures apply?</li></ol><h2>When your plans change.</h2><p>Tell the team before pickup if the inventory, route, dates or services change. Request a revised written estimate where applicable, and review it before authorizing the changed work.</p>'''),hero=('Know your estimate.<br>Know your next step.','Clear details up front help you compare the services, timing and terms that matter.'))

page('/about/','About Open Road Moving & Storage','Meet the purpose behind Open Road Moving & Storage, operated by TX Moving and Storage LLC. Long-distance moving with a clear plan and direct contact.',article('''<h2>A move is the start of something.</h2><p>A new home. A new city. A different pace. Open Road Moving &amp; Storage is built around helping you start that next chapter with a clear conversation about the move ahead.</p><h2>A national outlook, grounded in your route.</h2><p>Our long-distance focus includes pickup coverage centered on Texas, the Midwest and Northeast. We review your actual origin, destination, inventory and dates before confirming what is available.</p><h2>Clarity before commitment.</h2><p>We want you to understand the services being discussed, the company handling your move and the terms in your written estimate. Ask questions about timing, packing, access, payments and storage before booking.</p><h2>The company behind the name.</h2><p>Open Road Moving &amp; Storage is operated by TX Moving and Storage LLC. The company identifiers supplied for this service are USDOT 3266915 and MC 1030727. Your written moving documents identify the contracting company and the services and terms that apply to your shipment.</p><p><a href="https://safer.fmcsa.dot.gov/CompanySnapshot.aspx" target="_blank" rel="noopener noreferrer">Look up the company’s current FMCSA record</a> using USDOT 3266915.</p><h2>Let’s talk about your next address.</h2><p>Start with the two ZIP codes and your preferred date. The rest begins with a conversation.</p>'''),hero=('An open road.<br>A thoughtful start.','Moving forward begins with understanding the details.'))

page('/faqs/','Long-Distance Moving FAQs','Answers to questions about Open Road pickup coverage, moving quotes, delivery timing, packing, storage and changes to your move.',f'<section class="page-body"><div class="container prose">{faqs()}<h2>Still have a question?</h2><p>Share your route and what you need help with. We’ll discuss the details before you decide.</p>{call()}</div></section>',hero=('Good questions.<br>Clearer next steps.','Start here, then talk through anything specific to your move.'))

page('/get-a-quote/','Request a Moving Quote & Contact','Request your long-distance moving quote. Share your route, dates, home size and contact details, or call Open Road Moving & Storage.',f'''<section class="page-body"><div class="container contact-layout"><div class="contact-copy"><span class="eyebrow">LET’S START WITH YOUR ROUTE</span><h2>Your next address<br>starts a conversation.</h2><p>Tell us where you’re moving from and to, your preferred date and the help you need. We’ll review the details and confirm availability.</p><ul class="checklist"><li>Pickup coverage centered on Texas, the Midwest and Northeast.</li><li>Packing and storage needs discussed with your move.</li><li>Review the written estimate and terms before booking.</li></ul>{call()}<p><strong>Prefer email?</strong><br><a class="text-link" href="mailto:{EMAIL}">{EMAIL}</a></p><p>Your request is not a reservation, guaranteed date or final price. Your written moving agreement identifies the company handling your move.</p></div><div class="quote-card"><h2>Where are you headed?</h2><p class="card-intro">Start with a few details about your move.</p>{form('contact')}</div></div></section>''',hero=('Let’s plan your<br>next chapter.','Request a quote or speak with the team about your move.'))

page('/privacy/','Privacy Policy','How Open Road Moving & Storage uses information supplied through quote requests and contact links.',article(f'''<h2>Your quote-request information.</h2><p>When you submit a moving inquiry, you provide your name, contact details, move route, dates and any move notes you choose to include. TX Moving and Storage LLC, operating as Open Road Moving &amp; Storage, uses that information to respond, assess availability and discuss your requested services.</p><h2>Form delivery and website hosting.</h2><p>The website is hosted on GitHub Pages. Quote forms are processed by Web3Forms to deliver your inquiry to the inbox associated with our form access key. The contact email displayed on this website may differ from the form-notification inbox. These providers process technical information under their own policies.</p><p>See <a href="https://web3forms.com/privacy" target="_blank" rel="noopener noreferrer">Web3Forms’ privacy policy</a> and <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noopener noreferrer">GitHub’s privacy statement</a>.</p><h2>Use only what is needed.</h2><p>Do not include payment-card information, identification documents, passwords or other sensitive information in the quote form. Additional move details can be discussed directly when needed.</p><h2>Contact and sharing.</h2><p>Your inquiry is used for moving-service follow-up by phone or email. Information may be shared with service providers involved in fulfilling your requested move as needed for that purpose. Ask who will handle your shipment before booking.</p><h2>Website storage.</h2><p>This site does not install advertising trackers or save your form entries in browser storage. Hosting and form-processing providers may maintain technical logs or use security-related technologies on their own services.</p><h2>Questions or requests.</h2><p>To ask about information you submitted, request a correction or ask us to stop following up, email <a href="mailto:{EMAIL}">{EMAIL}</a>. We may need to verify your request and retain information needed for applicable obligations or an ongoing move.</p>'''),hero=('Your information.<br>A clear purpose.','Information you share is used to discuss and plan your requested move.'))

page('/terms/','Website Terms','Website information, quote requests, estimates and booking terms for Open Road Moving & Storage.',article('''<h2>Website information is a starting point.</h2><p>This website provides general information about moving services and a way to request contact. Service availability depends on your origin, destination, dates, inventory and requested services.</p><h2>A request is not a booking.</h2><p>Submitting a form, calling or emailing does not reserve a crew, vehicle, pickup date or delivery date. It is not a binding moving estimate or contract.</p><h2>Your written moving documents control.</h2><p>Review the written estimate, applicable service agreement, bill of lading and other documents provided for your move. Those documents identify the responsible company and govern charges, timing, payment terms, cancellation, valuation and claims. Ask for clarification before signing or paying.</p><h2>Company information.</h2><p>Open Road Moving &amp; Storage is operated by TX Moving and Storage LLC. USDOT 3266915 · MC 1030727. Registration information should be checked against current government records when making a booking decision.</p><h2>Links and availability.</h2><p>External links are provided for convenience. Third-party services, including form processing and phone service, operate under their own policies. If a form cannot be completed, use the call or email options on the contact page.</p>'''),hero=('Understand the next step.','Website inquiries and final moving agreements serve different purposes.'))

page('/thank-you/','Quote Request — Next Steps','Next steps after completing a moving quote request.',f'<section class="page-body"><div class="container prose"><h2>Keep an eye on your inbox and phone.</h2><p>If you reached this page after the form provider confirmed submission, your inquiry has been submitted for follow-up. This is not a booking or a final estimate.</p><p>If you did not receive a confirmation, or have a time-sensitive question, please call or email the team.</p>{call()}<p><a href="/how-it-works/">See what happens next →</a></p></div></section>',hero=('Your next chapter.<br>Let’s talk it through.','The next step is a review of your route, inventory and timing.'),noindex=True)
page('/404/','Page Not Found','Find your way back to Open Road Moving & Storage.',f'<section class="page-body"><div class="container prose"><h2>Let’s get you back on the road.</h2><p>This page may have moved. Visit the homepage or tell us about your move.</p><a class="button" href="/">Back to home →</a></div></section>',hero=('A small detour.','We couldn’t find that page.'),noindex=True)
